<template><ContentWrap><el-button type="primary" @click="open=true">新增智能体</el-button><el-table :data="rows"><el-table-column prop="name" label="名称"/><el-table-column prop="code" label="Code"/><el-table-column prop="realtimeMode" label="实时模式"/><el-table-column prop="memoryMode" label="记忆"/><el-table-column prop="status" label="状态"/></el-table><el-dialog v-model="open" title="智能体"><el-form :model="form"><el-input v-model="form.name" placeholder="名称"/><el-input v-model="form.code" placeholder="Code"/><AgentRouteForm v-model="form.realtimeMode"/><el-form-item v-if="form.realtimeMode!=='CASCADE'" label="Realtime Model"><el-input-number v-model="form.realtimeModelId"/></el-form-item><template v-if="form.realtimeMode!=='NATIVE'"><el-form-item label="ASR"><el-input-number v-model="form.asrModelId"/></el-form-item><el-form-item label="Chat"><el-input-number v-model="form.conversationModelId"/></el-form-item><el-form-item label="TTS"><el-input-number v-model="form.ttsModelId"/></el-form-item></template><el-form-item label="记忆读取"><el-switch v-model="form.memoryReadEnabled"/></el-form-item><el-form-item label="记忆写入"><el-switch v-model="form.memoryWriteEnabled"/></el-form-item></el-form><el-button @click="save">保存</el-button></el-dialog></ContentWrap></template><script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{AiAgentApi,type AgentVO}from'@/api/ai/agent';import AgentRouteForm from'./components/AgentRouteForm.vue';const rows=ref<AgentVO[]>([]),open=ref(false),form=reactive<any>({name:'',code:'',systemPromptId:0,realtimeMode:'NATIVE',memoryMode:'LONG_TERM',memoryReadEnabled:true,memoryWriteEnabled:true,knowledgeEnabled:false,status:'ENABLED'});async function load(){rows.value=await AiAgentApi.list()}async function save(){await AiAgentApi.create(form);open.value=false;await load()}onMounted(load)</script>